<div class="page-heading"><div><p class="eyebrow">Vendor workspace</p><h1>Orders</h1><p>Confirm, prepare, and mark each order ready for pickup.</p></div></div>
<form class="toolbar" method="get" action="<?= h(app_url('vendor.orders')) ?>"><input type="hidden" name="r" value="vendor.orders"><div class="form-field"><label for="status-filter">Show status</label><select id="status-filter" name="status"><option value="">All orders</option><?php foreach (ORDER_STATUSES as $candidate): ?><option value="<?= h($candidate) ?>"<?= $status === $candidate ? ' selected' : '' ?>><?= h(status_label($candidate)) ?></option><?php endforeach; ?></select></div><button class="button button-secondary" type="submit">Filter</button><a class="button button-secondary" href="<?= h(app_url('vendor.pos')) ?>">Open POS</a></form>
<?php if ($orders): ?><div class="stack">
  <?php foreach ($orders as $order): $next = Order::allowedNext($order['status']); ?>
    <article class="panel order-card">
      <div class="spread order-card-head"><div><p class="eyebrow" style="margin-bottom:3px"><?= h(format_datetime($order['created_at'])) ?></p><h2 class="panel-title" style="margin:0"><?= h($order['order_number']) ?></h2><p class="muted small" style="margin:4px 0 0"><?= h($order['student_name'] ?: 'Point of sale') ?> · <?= h($order['pickup_location']) ?></p></div><div class="stack" style="justify-items:end;gap:5px"><?php $status=$order['status']; require APP_ROOT . '/views/components/status-badge.php'; ?><?php $status=$order['payment_status'] ?? 'UNPAID'; require APP_ROOT . '/views/components/status-badge.php'; ?></div></div>
      <div class="order-card-content"><div><strong>Items</strong><p><?= h($order['item_summary'] ?: '—') ?></p><strong>Total · <?= h(money($order['total'])) ?></strong></div>
      <?php if ($next): ?><form method="post" action="<?= h(app_url('vendor.order.status')) ?>" class="order-action-form" data-submit-feedback><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int) $order['id'] ?>"><div class="form-field"><label for="next-<?= (int) $order['id'] ?>">Next step</label><select id="next-<?= (int) $order['id'] ?>" name="status" required><?php foreach ($next as $choice): ?><option value="<?= h($choice) ?>"><?= h(status_label($choice)) ?></option><?php endforeach; ?></select></div><?php if (in_array('COMPLETED', $next, true)): ?><div class="form-field"><label for="cash-<?= (int) $order['id'] ?>">Cash received (₱) <span class="muted">(only to complete)</span></label><input id="cash-<?= (int) $order['id'] ?>" name="cash_received" type="number" min="0" max="1000000" step="0.01" inputmode="decimal" placeholder="<?= h(number_format((float) $order['total'], 2, '.', '')) ?>" required></div><?php endif; ?><div class="form-field"><label for="note-<?= (int) $order['id'] ?>">Note <span class="muted">(optional)</span></label><input id="note-<?= (int) $order['id'] ?>" name="note" maxlength="240" placeholder="Short status note"></div><button class="button button-small" type="submit" data-loading-text="Updating…">Update</button></form><?php endif; ?></div>
      <?php if ($order['status'] === 'READY' && $order['payment_status'] === 'UNPAID'): ?><p class="cash-note" style="margin-bottom:0">At pickup, enter cash received and choose “Completed” to record payment.</p><?php endif; ?>
    </article>
  <?php endforeach; ?>
</div><?php $routeName='vendor.orders'; $perPage=$limit; $queryParams=$status ? ['status'=>$status] : []; require APP_ROOT . '/views/components/pagination.php'; ?>
<?php else: ?><div class="empty-state"><div class="empty-icon" aria-hidden="true">✓</div><h2>No orders in this view</h2><p>New student orders will appear here when placed.</p><a class="button button-secondary" href="<?= h(app_url('vendor.dashboard')) ?>">Back to overview</a></div><?php endif; ?>
